probe=r'''
window.__ownedMigrationProof=()=>{
 const live=G,liveJson=JSON.stringify(G),base=JSON.parse(liveJson),initial={rng:rngState,owned:migrationReportOwner===G,recent:copyCooperativeState(migrationRecent),observed:migrationObservedDay,counts:{...migrationSessionCounts}},store=createOwnedMigrationStore(base,copyCooperativeState(initial),__ownedReference),rows=[];let oracle=JSON.parse(liveJson),oracleContext=copyCooperativeState(initial);
 const saveGlobals=()=>({G,rng:rngState,owner:migrationReportOwner,recent:migrationRecent,observed:migrationObservedDay,counts:migrationSessionCounts}),restore=s=>{G=s.G;rngState=s.rng;migrationReportOwner=s.owner;migrationRecent=s.recent;migrationObservedDay=s.observed;migrationSessionCounts=s.counts;roadNetwork=null;roadGraphOwner=null;cacheBuildingsFor=null;transitTopologyCache=null;transitDailyCache=null;};
 function ordinary(day){const saved=saveGlobals();try{G=oracle;G.day=day;rngState=oracleContext.rng;migrationReportOwner=oracleContext.owned?G:null;migrationRecent=oracleContext.recent;migrationObservedDay=oracleContext.observed;migrationSessionCounts=oracleContext.counts;roadNetwork=null;cacheBuildingsFor=null;let start=performance.now();const backup=copyCooperativeState(G),backupMs=performance.now()-start;if(backup===G||backup.day!==day)throw Error('Backup control failed');start=performance.now();graph();const graphMs=performance.now()-start;start=performance.now();const departures=outwardMigration(),ms=performance.now()-start;oracleContext={rng:rngState,owned:migrationReportOwner===G,recent:copyCooperativeState(migrationRecent),observed:migrationObservedDay,counts:{...migrationSessionCounts}};return {departures,ms,backupMs,graphMs};}finally{restore(saved);}}
 let observedBoundaries=0;
 for(let i=0;i<8;i++){const day=41700+i*30,before=store.exportCommitted(),published=store.current;let expected,result;const ownedCall=()=>store.run(day,{observe:()=>{observedBoundaries++;if(store.current!==published||store.exportCommitted()!==before)throw Error('Published read/export changed inside phase');}});if(i%2){result=ownedCall();expected=ordinary(day);}else{expected=ordinary(day);result=ownedCall();}if(result.departures!==expected.departures||JSON.stringify(store.current)!==JSON.stringify(oracle)||JSON.stringify(store.context)!==JSON.stringify(oracleContext))throw Error('Owned migration diverged');rows.push({day,order:i%2?'owned-first':'control-first',...expected,...result});}

 // Reset to the same real terminal input so every fault reaches a real departure.
 const faultResults=[],externalBefore=saveGlobals(),externalJson=JSON.stringify({recent:migrationRecent,observed:migrationObservedDay,counts:migrationSessionCounts});for(const faultAt of ['planned','owned','person','workers','cash','tenancy','report','story','recompute','before-commit']){const candidate=createOwnedMigrationStore(JSON.parse(liveJson),copyCooperativeState(initial),__ownedReference),before=candidate.exportCommitted();let failed=false;try{candidate.run(41700,{faultAt});}catch(e){if(!e.message.includes('Injected owned fault'))throw e;failed=true;}if(!failed)throw Error('Boundary not reached: '+faultAt);if(candidate.exportCommitted()!==before)throw Error('Fault changed publication/export');if(G!==externalBefore.G||rngState!==externalBefore.rng||migrationReportOwner!==externalBefore.owner||JSON.stringify({recent:migrationRecent,observed:migrationObservedDay,counts:migrationSessionCounts})!==externalJson)throw Error('Fault leaked external state');const retry=candidate.run(41700);const expectedStore=createOwnedMigrationStore(JSON.parse(liveJson),copyCooperativeState(initial),__ownedReference);expectedStore.run(41700);if(candidate.exportCommitted()!==expectedStore.exportCommitted()||JSON.stringify(candidate.context)!==JSON.stringify(expectedStore.context))throw Error('Fault continuation differs');faultResults.push({faultAt,departures:retry.departures});}

 // Focused branch fixture: retain actual people, jobs and funds; change only
 // distress history/RNG and attach occupancy lists from existing residents.
 const focused=JSON.parse(liveJson);for(const h of focused.households){h.stress=0;h.worklessness=0;}const employee=focused.people.find(p=>!p.deceased&&!p.movedAway&&p.job>=0&&focused.firms[p.job]?.workers.includes(p.id));if(!employee)throw Error('No recorded employee for coverage');const fh=focused.households[employee.hh],fb=focused.buildings.find(b=>b.id===fh.home);fh.stress=90;fh.worklessness=100;fh.essentialDueTrend=1e9;fb.units=focused.households.filter(h=>h.home===fb.id&&h.people.length).map(h=>h.id);fb.legacySharedTenants=fb.units.slice();const focusedJson=JSON.stringify(focused),focusedContext={...copyCooperativeState(initial),rng:0};oracle=JSON.parse(focusedJson);oracleContext=copyCooperativeState(focusedContext);const focusedExpected=ordinary(41700),focusedExpectedJson=JSON.stringify(oracle),focusedExpectedContext=JSON.stringify(oracleContext);if(!focusedExpected.departures)throw Error('Focused departure not reached');const focusedFaults=[];
 for(const faultAt of ['planned','owned','person','workers','cash','tenancy','report','story','recompute','before-commit']){const candidate=createOwnedMigrationStore(JSON.parse(focusedJson),copyCooperativeState(focusedContext),__ownedReference),before=candidate.exportCommitted();let failed=false;try{candidate.run(41700,{faultAt});}catch(e){if(!e.message.includes('Injected owned fault'))throw e;failed=true;}if(!failed||candidate.exportCommitted()!==before)throw Error('Focused fault publication changed');const retried=candidate.run(41700);if(!retried.metrics.ownedFirms||JSON.stringify(candidate.current)!==focusedExpectedJson||JSON.stringify(candidate.context)!==focusedExpectedContext)throw Error('Worker/tenancy retry differs');focusedFaults.push({faultAt,ownedFirms:retried.metrics.ownedFirms,ownedBuildings:retried.metrics.ownedBuildings});}

 const guarded=createOwnedMigrationStore(JSON.parse(focusedJson),copyCooperativeState(focusedContext),__ownedReference),guardedBefore=guarded.exportCommitted(),originalRecompute=recompute;let undeclaredWriteRejected=false;try{recompute=function(){G.policy.minWage++;originalRecompute();};guarded.run(41700);}catch(e){undeclaredWriteRejected=e instanceof TypeError;}finally{recompute=originalRecompute;}if(!undeclaredWriteRejected||guarded.exportCommitted()!==guardedBefore)throw Error('Undeclared helper write escaped rollback');let sourceMismatchRejected=false;try{createOwnedMigrationStore({},copyCooperativeState(initial),'unreviewed source');}catch(e){sourceMismatchRejected=e.message.includes('source changed');}if(!sourceMismatchRejected)throw Error('Review pin was not enforced');
 return {auditMs:store.auditMs,rows,observedBoundaries,faultResults,focusedFixture:{household:fh.id,existingEmployee:employee.id,noNewJobsOrFunds:true,syntheticDistressHistory:true,faults:focusedFaults},exactModelAndExternalRngReports:true,undeclaredWriteRejected,sourceMismatchRejected,publishedExportStable:true,liveGameUnchanged:JSON.stringify(live)===liveJson};
};
'''
